type RequestCtx = { readonly signal: AbortSignal; readonly deadlineMs: number };

async function handle(ctx: RequestCtx, url: string): Promise<Response> {
  const remaining = ctx.deadlineMs - performance.now();
  if (remaining <= 0) throw new DeadlineExceeded();
  const signal = AbortSignal.any([ctx.signal, AbortSignal.timeout(remaining)]);
  return fetch(url, { signal });        // same ctx is forwarded to nested calls
}
